CREATE TEMP VIEW _seed_members AS
SELECT * FROM members WHERE email = 'admin@example.com'
 OR email ~ '^(kim|lee|park|choi|jung|kang|cho|yoon|jang|lim)[.](minjun|seoyeon|doyun|jiwoo|siwoo|hayoon|yejun|subin|jiho|yujin)[0-9]{4}@example[.]com$';
CREATE TEMP VIEW _seed_categories AS
SELECT c.* FROM categories c LEFT JOIN categories parent ON parent.category_id=c.parent_id
WHERE EXISTS (
    SELECT 1 FROM jsonb_array_elements((SELECT data->'categories' FROM _seed_catalog)) source
    LEFT JOIN jsonb_array_elements((SELECT data->'categories' FROM _seed_catalog)) source_parent
        ON source_parent->>'category_id'=source->>'parent_id'
    WHERE c.name=source->>'name' AND
        ((c.parent_id IS NULL AND source->>'parent_id' IS NULL)
            OR (parent.name=source_parent->>'name' AND parent.parent_id IS NULL))
);
CREATE TEMP VIEW _seed_products AS
SELECT p.* FROM products p WHERE EXISTS (
    SELECT 1 FROM stock_histories h JOIN members m ON m.member_id=h.actor_id
    WHERE h.product_id=p.product_id AND h.reason='INITIAL' AND m.email='admin@example.com'
);
CREATE TEMP VIEW _seed_orders AS SELECT * FROM orders WHERE member_id IN (SELECT member_id FROM _seed_members);
CREATE TEMP VIEW _seed_reviews AS SELECT * FROM reviews WHERE member_id IN (SELECT member_id FROM _seed_members);
CREATE TEMP VIEW _seed_inquiries AS SELECT * FROM inquiries WHERE member_id IN (SELECT member_id FROM _seed_members);

CREATE TEMP TABLE _seed_counts (
    table_name text PRIMARY KEY, expected bigint NOT NULL, condition_sql text NOT NULL,
    before_count bigint, seeded_count bigint
) ON COMMIT DROP;
